-- ============================================================
-- 25 wm new patient form v3
--
-- Generated by scripts/publish-wm-new-patient-form.ts from the form definition
-- in src/lib/services/weight-management.ts. Regenerate rather than edit.
--
-- Publishes a NEW version. Nothing already answered changes: submissions stay
-- bound to the version they were completed against, so the two v1 requests
-- still render as the questions those patients were actually asked.
--
-- What this version contains — the whole form, not a diff. Each run publishes
-- whatever the definition currently says, so read this as a description of the
-- questionnaire rather than a list of what moved since last time:
--
--   a pathway step. It explains this is an online service, offers
--            face-to-face care, and HARD STOPS if that is chosen — offering
--            the separate Karsons programme. Every later step is hidden until
--            the patient chooses to continue online, so somebody told to book
--            elsewhere cannot carry on and submit anyway.
--
--   ADDED    identity: first name, last name, date of birth, gender, phone,
--            email, address, GP surgery. v1 asked forty-two questions and not
--            one of them was a name, so every submission arrived unattached to
--            a patient record — the review queue showed "Unmatched patient"
--            and approving one raised no prescription, because there was
--            nobody to raise it for.
--
--   ADDED    the route question the client supplied: "Are you currently
--            receiving, or have you recently received, weight-management
--            treatment from another clinic?" No routes to the standard
--            questions; Yes reveals a transfer step.
--
--   ADDED    a transfer step — prior clinic, current medicine and strength,
--            when that strength started, last supply, starting weight, side
--            effects. These are the categories the client named. The exact
--            question wording and what counts as acceptable proof are still
--            with him, and are deliberately not invented here.
--
--   ADDED    evidence: photo ID, a photograph of the patient, and evidence of
--            current weight, for everyone. Evidence of the current
--            prescription for transfers only.
--
--   ADDED    a supply step — delivery or collection. The branch is asked only
--            for collection and an address only for delivery. It is not an
--            appointment: the client is explicit that neither Weight
--            Management journey creates one.
--
--   CHANGED  consent. The clause promising "an appointment to see a pharmacist
--            in person at any time" described a service this is not. It now
--            says the patient can contact the team and will be told if they
--            need to be seen.
--
--   CHANGED  title and description. No copy remains telling a patient to
--            complete this before an appointment.
--
-- Eligibility is NOT enforced in the form. The client gave the BMI criteria
-- but has not said what happens to somebody outside them — refused at the
-- form, or accepted for a pharmacist to judge. The assessment is computed and
-- shown to staff; nobody is silently passed as eligible.
--
-- Safe to run more than once? NO. Each run publishes another version. Run once.
-- ============================================================

begin;

with next as (
  select coalesce(max(version), 0) + 1 as v
    from public.form_version
   where service_id = 'a8734e8a-b774-5363-92f5-3a5269d908c4'::uuid
),
inserted as (
  insert into public.form_version (organisation_id, service_id, version, schema, published_at)
  select 'e91b8b9a-54e8-55a1-8412-d3ade3da0b53'::uuid,
         'a8734e8a-b774-5363-92f5-3a5269d908c4'::uuid,
         next.v,
         $json${"schemaVersion":1,"title":"Weight Management — New Patient","description":"A few questions about your health, so a pharmacist can decide whether this treatment is right for you. It takes about ten minutes and you can stop and come back.","numberQuestions":true,"estimatedMinutes":10,"completionMessage":"Thank you. A pharmacist will review your answers and telephone you on the number you gave us, usually within one working day. Nothing is supplied until you have spoken to them.","consentClauses":[{"id":"risks","text":"I have received information on the risks and benefits of the medicine, and I have had the opportunity to ask questions."},{"id":"accurate","text":"The medical information I have provided is true and accurate to the best of my knowledge, and I consent to the medicine being supplied."},{"id":"reliance","text":"I understand that the supply of this medicine is based on the information I have given, and that if it is inaccurate it could negatively affect my treatment."},{"id":"contact","text":"I understand this is a remote service, that I can contact the pharmacy team at any time to discuss my treatment, and that I will be told if I need to be seen in person."},{"id":"storage","text":"I understand that my personal information — name, surname, email, telephone, date of birth, address and GP details — will be securely stored and processed in line with data protection regulations."},{"id":"transmission","text":"I authorise the collection, storage, and secure transmission of my information for the purposes mentioned above."},{"id":"gp","text":"I acknowledge that my GP will be notified of any prescription issued."},{"id":"rights","text":"I understand I can speak to a member of staff about any queries regarding my consultation or the processing of my personal data, by contacting the pharmacy."}],"clinicianDeclarations":[{"id":"accurate","text":"I confirm the patient has provided accurate information and disclosed all medical conditions and allergies."},{"id":"leaflet","text":"I confirm I have provided a patient information leaflet and discussed as required."},{"id":"side-effects","text":"I confirm I have advised the patient on possible side effects and their management."},{"id":"pregnancy-suspected","text":"I have made the patient aware they should discontinue treatment and contact their supplier or GP if they suspect pregnancy."},{"id":"pregnancy-planned","text":"I have made the patient aware they should contact their supplier if planning pregnancy, as treatment must be discontinued."},{"id":"contraception","text":"I confirm the patient has been advised regarding contraception interactions and risks related to delayed gastric emptying."},{"id":"insulin","text":"I confirm the patient has received GP advice if also taking insulin or sulfonylureas, with monitoring in place."}],"steps":[{"id":"pathway","title":"How would you like to be seen?","fields":[{"id":"pathwayIntro","type":"infoBlock","label":"This is an online service. You will not normally see anyone in person — a pharmacist reviews your answers, telephones you, and decides whether treatment is suitable. If at any point they think you should be seen, they will tell you."},{"id":"pathwayChoice","type":"select","label":"Which would you prefer?","required":true,"presentation":"radioList","options":[{"value":"remote","label":"Continue online"},{"value":"in_person","label":"I would rather see someone in person"}],"warnWhen":[{"value":"in_person","severity":"stop","message":"No problem — this online service is not the right fit, but Karsons Pharmacy runs a face-to-face weight management programme you can join instead. You do not need to finish this form.","offerReferral":true}]}]},{"id":"about-you","title":"About you","description":"So we know whose record this is, and how to reach you.","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"firstName","type":"shortText","label":"First name","required":true,"halfWidth":true},{"id":"lastName","type":"shortText","label":"Last name","required":true,"halfWidth":true},{"id":"dateOfBirth","type":"dateOfBirth","label":"Date of birth","required":true},{"id":"gender","type":"select","label":"Gender","helpText":"We ask only so we know which health questions apply to you.","required":true,"presentation":"segmented","options":[{"value":"female","label":"Female"},{"value":"male","label":"Male"},{"value":"other","label":"Other"}]},{"id":"phone","type":"phone","label":"Phone number","required":true,"halfWidth":true,"helpText":"A pharmacist will call you on this number."},{"id":"email","type":"email","label":"Email address","required":true,"halfWidth":true},{"id":"address","type":"address","label":"Home address","required":true},{"id":"gpSurgery","type":"shortText","label":"Your GP surgery","helpText":"We tell them what has been supplied."},{"id":"otherClinic","type":"yesNo","label":"Are you currently receiving, or have you recently received, weight-management treatment from another clinic?","required":true,"presentation":"pills","helpText":"This changes which questions we need to ask, and what evidence we need."}]},{"id":"measurements","title":"Your measurements","description":"Enter these in whichever units you know them in — we convert them.","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"height","type":"measurement","label":"Height","measurementKind":"height","required":true},{"id":"weight","type":"measurement","label":"Current weight","measurementKind":"weight","required":true},{"id":"waist","type":"measurement","label":"Waist circumference","measurementKind":"length","required":true},{"id":"bmi","type":"derived","label":"Calculated BMI","calculation":"bmi","calculationInputs":["weight","height"]}]},{"id":"transfer","title":"Your current treatment","description":"Because you told us you are already being treated elsewhere.","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"},{"field":"otherClinic","operator":"eq","value":"yes"}],"fields":[{"id":"priorClinicName","type":"shortText","label":"Which clinic or pharmacy are you with?","required":true},{"id":"priorMedicine","type":"select","label":"Which medicine and strength are you currently on?","required":true,"presentation":"dropdown","options":[{"value":"mounjaro_2.5mg","label":"Mounjaro 2.5mg","metadata":{"medicine":"Mounjaro","strength":"2.5mg","ladderIndex":0}},{"value":"mounjaro_5mg","label":"Mounjaro 5mg","metadata":{"medicine":"Mounjaro","strength":"5mg","ladderIndex":1}},{"value":"mounjaro_7.5mg","label":"Mounjaro 7.5mg","metadata":{"medicine":"Mounjaro","strength":"7.5mg","ladderIndex":2}},{"value":"mounjaro_10mg","label":"Mounjaro 10mg","metadata":{"medicine":"Mounjaro","strength":"10mg","ladderIndex":3}},{"value":"mounjaro_12.5mg","label":"Mounjaro 12.5mg","metadata":{"medicine":"Mounjaro","strength":"12.5mg","ladderIndex":4}},{"value":"mounjaro_15mg","label":"Mounjaro 15mg","metadata":{"medicine":"Mounjaro","strength":"15mg","ladderIndex":5}},{"value":"wegovy_0.25mg","label":"Wegovy 0.25mg","metadata":{"medicine":"Wegovy","strength":"0.25mg","ladderIndex":0}},{"value":"wegovy_0.5mg","label":"Wegovy 0.5mg","metadata":{"medicine":"Wegovy","strength":"0.5mg","ladderIndex":1}},{"value":"wegovy_1mg","label":"Wegovy 1mg","metadata":{"medicine":"Wegovy","strength":"1mg","ladderIndex":2}},{"value":"wegovy_1.7mg","label":"Wegovy 1.7mg","metadata":{"medicine":"Wegovy","strength":"1.7mg","ladderIndex":3}},{"value":"wegovy_2.4mg","label":"Wegovy 2.4mg","metadata":{"medicine":"Wegovy","strength":"2.4mg","ladderIndex":4}}]},{"id":"priorStartedOn","type":"date","label":"When did you start this strength?","required":true,"halfWidth":true},{"id":"priorLastSupply","type":"date","label":"When was your last supply?","required":true,"halfWidth":true},{"id":"priorStartingWeight","type":"measurement","label":"What did you weigh when you started treatment?","measurementKind":"weight","required":true,"helpText":"Your progress is measured from this, so an approximate figure is better than none."},{"id":"priorSideEffects","type":"yesNo","label":"Have you had any side effects on your current treatment?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"priorSideEffectsDetail","type":"longText","label":"Please describe them","required":true}]}]},{"id":"priorClinicReason","type":"longText","label":"Why are you moving to us?","helpText":"Optional, but it helps the pharmacist understand your treatment so far."}]},{"id":"medical-history","title":"Medical history","description":"These questions decide whether this treatment is safe for you.","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"contraindications","type":"checkboxGroup","label":"Do you have any of the following conditions?","helpText":"Tick all that apply, or tick \"None of the above\".","required":true,"presentation":"checkList","options":[{"value":"heart_failure","label":"Severe heart failure"},{"value":"retinopathy","label":"Diabetic retinopathy"},{"value":"pancreatitis","label":"Pancreatitis (current or previous)"},{"value":"gastroparesis","label":"Gastroparesis"},{"value":"ibd","label":"Ulcerative colitis or Crohn's disease"},{"value":"thyroid_cancer","label":"History or family history of thyroid cancer"},{"value":"men2","label":"History or family history of MEN2"},{"value":"cancer","label":"Any cancer, chemotherapy or radiotherapy"},{"value":"none","label":"None of the above"}]},{"id":"gallbladder","type":"yesNo","label":"Do you have gallbladder or bile duct issues?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"gallbladderDetail","type":"checkboxGroup","label":"Could you tell us a little more?","required":true,"presentation":"checkList","options":[{"value":"current","label":"Currently experiencing gallstones"},{"value":"previous","label":"Previously experienced gallstones"},{"value":"removed","label":"I had my gallbladder removed"},{"value":"other","label":"Other"}]},{"id":"gallbladderOther","type":"longText","label":"Please give any other details"}]}]},{"id":"liver","type":"yesNo","label":"Do you have liver impairment?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"liverDetail","type":"checkboxGroup","label":"Which applies to you?","required":true,"presentation":"checkList","options":[{"value":"nafld","label":"Non-alcoholic fatty liver disease"},{"value":"nash","label":"NASH"},{"value":"moderate_severe","label":"Moderate or severe liver impairment"},{"value":"other","label":"Other"}]},{"id":"liverOther","type":"longText","label":"Please give any other details"}]}]},{"id":"diabetes","type":"select","label":"Do you have diabetes?","required":true,"presentation":"radioList","options":[{"value":"no","label":"No"},{"value":"prediabetes","label":"Pre-diabetes, or diet-controlled"},{"value":"medicated","label":"Yes — and I take medicine for it"}]},{"id":"weightConditions","type":"multiSelect","label":"Do you have any weight-related conditions?","helpText":"Select all that apply.","presentation":"chips","options":[{"value":"none","label":"None of the above"},{"value":"depression","label":"Depression linked to weight"},{"value":"reflux","label":"Acid reflux / GORD"},{"value":"hypertension","label":"High blood pressure"},{"value":"ed","label":"Erectile dysfunction"},{"value":"cvd","label":"Cardiovascular disease"},{"value":"osteoarthritis","label":"Knee or hip osteoarthritis"},{"value":"asthma","label":"Asthma"},{"value":"copd","label":"COPD"},{"value":"sleep_apnoea","label":"Obstructive sleep apnoea"},{"value":"cholesterol","label":"High cholesterol"},{"value":"pcos","label":"PCOS"},{"value":"other","label":"Other"}],"reveals":[{"whenValue":"other","fields":[{"id":"weightConditionsOther","type":"longText","label":"Please tell us more"}]}]}]},{"id":"habits-safety","title":"Habits and safety","description":"Please answer honestly — nothing here is judged, and it changes what is safe to supply.","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"madeSick","type":"yesNo","label":"Have you ever made yourself sick to lose weight?","required":true,"presentation":"pills"},{"id":"laxatives","type":"yesNo","label":"Have you ever taken laxatives to lose weight?","required":true,"presentation":"pills"},{"id":"controlEating","type":"yesNo","label":"Do you struggle to control your eating?","required":true,"presentation":"pills"},{"id":"eatingDisorder","type":"yesNo","label":"Have you ever been diagnosed with an eating disorder?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"eatingDisorderDetail","type":"longText","label":"Please tell us more","required":true}]}]},{"id":"otherMeds","type":"yesNo","label":"Are you taking any other medication?","helpText":"Including anything bought over the counter.","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"otherMedsDetail","type":"longText","label":"Which medicines, and what dose?","required":true}]}]},{"id":"allergies","type":"yesNo","label":"Do you have any allergies?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"allergiesDetail","type":"longText","label":"What are you allergic to, and what happens?","required":true}]}]},{"id":"recentSurgery","type":"yesNo","label":"Have you had surgery in the last 3 months?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"recentSurgeryDetail","type":"longText","label":"What surgery, and when?","required":true}]}]}]},{"id":"request","title":"What you are asking for","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"recentWeightLossMeds","type":"select","label":"Have you taken any weight loss medication in the last 2 weeks?","required":true,"presentation":"radioList","options":[{"value":"none","label":"Not currently taking any"},{"value":"wegovy","label":"Wegovy"},{"value":"mounjaro","label":"Mounjaro"},{"value":"ozempic","label":"Ozempic"},{"value":"other","label":"Other"}],"reveals":[{"whenValue":"other","fields":[{"id":"recentMedsOther","type":"shortText","label":"Which medicine?","required":true}]}]},{"id":"everUsedWeightLossMeds","type":"yesNo","label":"Have you ever used weight loss medication before?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"previousMeds","type":"multiSelect","label":"Which have you used?","required":true,"presentation":"chips","options":[{"value":"wegovy","label":"Wegovy"},{"value":"mounjaro","label":"Mounjaro"},{"value":"saxenda","label":"Saxenda"},{"value":"orlistat","label":"Xenical / Orlistat"},{"value":"ozempic","label":"Ozempic"},{"value":"other","label":"Other"}]},{"id":"previousMedsDetail","type":"longText","label":"How did you get on with them?"}]}]},{"id":"requestedMedicine","type":"select","label":"Which medicine and strength are you requesting?","required":true,"presentation":"dropdown","storeMetadataAs":"requestedMedicineDetail","options":[{"value":"mounjaro_2.5mg","label":"Mounjaro 2.5mg","metadata":{"medicine":"Mounjaro","strength":"2.5mg","ladderIndex":0}},{"value":"mounjaro_5mg","label":"Mounjaro 5mg","metadata":{"medicine":"Mounjaro","strength":"5mg","ladderIndex":1}},{"value":"mounjaro_7.5mg","label":"Mounjaro 7.5mg","metadata":{"medicine":"Mounjaro","strength":"7.5mg","ladderIndex":2}},{"value":"mounjaro_10mg","label":"Mounjaro 10mg","metadata":{"medicine":"Mounjaro","strength":"10mg","ladderIndex":3}},{"value":"mounjaro_12.5mg","label":"Mounjaro 12.5mg","metadata":{"medicine":"Mounjaro","strength":"12.5mg","ladderIndex":4}},{"value":"mounjaro_15mg","label":"Mounjaro 15mg","metadata":{"medicine":"Mounjaro","strength":"15mg","ladderIndex":5}},{"value":"wegovy_0.25mg","label":"Wegovy 0.25mg","metadata":{"medicine":"Wegovy","strength":"0.25mg","ladderIndex":0}},{"value":"wegovy_0.5mg","label":"Wegovy 0.5mg","metadata":{"medicine":"Wegovy","strength":"0.5mg","ladderIndex":1}},{"value":"wegovy_1mg","label":"Wegovy 1mg","metadata":{"medicine":"Wegovy","strength":"1mg","ladderIndex":2}},{"value":"wegovy_1.7mg","label":"Wegovy 1.7mg","metadata":{"medicine":"Wegovy","strength":"1.7mg","ladderIndex":3}},{"value":"wegovy_2.4mg","label":"Wegovy 2.4mg","metadata":{"medicine":"Wegovy","strength":"2.4mg","ladderIndex":4}}]},{"id":"doseRequest","type":"select","label":"Is this a starting dose, or a change?","required":true,"presentation":"radioList","options":[{"value":"starting","label":"Starting dose"},{"value":"same","label":"Stay on the same dose"},{"value":"increase","label":"Increase dose"},{"value":"decrease","label":"Decrease dose"}]},{"id":"supplyDuration","type":"select","label":"How much supply are you asking for?","helpText":"One month is one pen — four doses, one a week.","required":true,"presentation":"segmented","options":[{"value":"1","label":"1 pen (4 weeks)"},{"value":"2","label":"2 pens (8 weeks)"}]}]},{"id":"evidence-safety","title":"Evidence and safety","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"photoId","type":"fileUpload","label":"Photo ID","helpText":"Passport, driving licence or another photographic ID. JPG, PNG or PDF.","required":true},{"id":"patientPhoto","type":"photoCapture","label":"A photo of yourself","helpText":"Taken now, so we can check it against your ID.","required":true},{"id":"measurementEvidence","type":"fileUpload","label":"Photo showing your current weight","helpText":"A picture of your scales reading, or a recent record from your GP.","required":true},{"id":"evidence","type":"fileUpload","label":"Photo of your current prescription or medicine box","helpText":"So we can confirm the medicine and strength you are already on.","required":true,"visibleWhen":[{"field":"otherClinic","operator":"eq","value":"yes"}]},{"id":"pregnancy","type":"yesNo","label":"Are you pregnant, breastfeeding, or planning a pregnancy?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"neq","value":"male"}],"warnWhen":[{"value":"yes","severity":"stop","message":"This treatment cannot be supplied during pregnancy, breastfeeding, or while planning a pregnancy. Please speak to a pharmacist."}]},{"id":"oralContraception","type":"yesNo","label":"Are you taking oral contraception (the pill)?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"neq","value":"male"}],"warnWhen":[{"value":"yes","severity":"warn","message":"This medicine can slow digestion, which may affect how well the pill is absorbed. A pharmacist will discuss this with you."}]},{"id":"bleedingDisorder","type":"yesNo","label":"Do you have a bleeding disorder?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"eq","value":"male"}]},{"id":"anythingElse","type":"yesNo","label":"Is there anything else we should know?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"anythingElseDetail","type":"longText","label":"Please tell us","required":true}]}]}]},{"id":"supply","title":"Getting your medicine","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"fulfilmentMethod","type":"select","label":"How would you like to receive it?","required":true,"presentation":"radioList","options":[{"value":"delivery","label":"Post it to me"},{"value":"collection","label":"I will collect it from the pharmacy"}]},{"id":"collectionBranch","type":"select","label":"Which pharmacy will you collect from?","required":true,"presentation":"radioList","options":[{"value":"91d6d112-e3c0-5676-8b3c-029428a17e97","label":"Kirk Michael","metadata":{"branchId":"91d6d112-e3c0-5676-8b3c-029428a17e97"}},{"value":"2e9d53ca-ce0a-50a3-9ad0-e639a45741b2","label":"Onchan","metadata":{"branchId":"2e9d53ca-ce0a-50a3-9ad0-e639a45741b2"}}],"storeMetadataAs":"collectionBranchDetail","visibleWhen":[{"field":"fulfilmentMethod","operator":"eq","value":"collection"}]},{"id":"deliveryAddress","type":"address","label":"Delivery address","helpText":"Leave blank to use your home address above.","visibleWhen":[{"field":"fulfilmentMethod","operator":"eq","value":"delivery"}]}]},{"id":"consent","title":"Consent","visibleWhen":[{"field":"pathwayChoice","operator":"eq","value":"remote"}],"fields":[{"id":"consent","type":"consentList","label":"Consent to treatment","required":true},{"id":"signature","type":"signature","label":"Please sign below","required":true}]}]}$json$::jsonb,
         now()
    from next
  returning id, version
)
update public.service
   set published_form_version_id = inserted.id
  from inserted
 where public.service.id = 'a8734e8a-b774-5363-92f5-3a5269d908c4'::uuid;

commit;

-- ── Verify ──────────────────────────────────────────────────
-- Expect: the next version, 10 steps, and 1 / 3 / 1 / 1 across the flags.
select s.slug,
       fv.version,
       jsonb_array_length(fv.schema->'steps')                          as steps,
       (select count(*) from jsonb_array_elements(fv.schema->'steps') st
         where st->>'id' = 'pathway')                                  as has_pathway_gate,
       (select count(*) from jsonb_array_elements(fv.schema->'steps') st,
                             jsonb_array_elements(st->'fields') f
         where f->>'id' in ('firstName','lastName','dateOfBirth'))     as identity_fields,
       (select count(*) from jsonb_array_elements(fv.schema->'steps') st
         where st->>'id' = 'transfer')                                 as has_transfer_branch,
       (select count(*) from jsonb_array_elements(fv.schema->'steps') st
         where st->>'id' = 'supply')                                   as has_supply_step,
       (fv.schema::text like '%before your appointment%')              as still_says_appointment
  from public.service s
  join public.form_version fv on fv.id = s.published_form_version_id
 where s.slug = 'weight-management-first';
